function makeLibraryStory([key,title,theme,scene,hero,place,friend,treasure,challenge]){return [key,{theme,title,scene,start:`${hero} arrived at ${place} expecting an ordinary day. Instead, ${friend} rushed over with surprising news about ${treasure}. Only a careful reader and a courageous explorer could help.`,choices:[{label:'🧭 Follow the first clue',text:`${hero} followed a trail of clues through ${place}. Each sign pointed towards ${treasure}, but the path became stranger at every turn.`},{label:'💬 Ask a new friend',text:`${hero} stopped to listen to ${friend}. Together they made a thoughtful plan to search for ${treasure} and ${challenge}.`}],pages:[`A message revealed that ${treasure} could ${challenge}. ${hero} checked every detail and shared ideas with ${friend} before they continued.`,`The route became difficult, but ${hero} stayed calm. A surprising clue appeared in the place they had almost forgotten to check.`,`At last, they found ${treasure} and used it to ${challenge}. Everyone celebrated, and ${hero} learned that curiosity, courage, and teamwork can solve enormous problems.`],extraChoices:[{prompt:'How should they investigate the next clue?',options:[{label:'🔎 Look carefully',effect:`${hero} examined every tiny detail and noticed a mark that everyone else had missed.`},{label:'👂 Stop and listen',effect:`${hero} listened quietly and heard a gentle sound pointing them in the right direction.`}]},{prompt:'What should they do when the route gets difficult?',options:[{label:'🤝 Work together',effect:`${hero} and ${friend} shared their ideas and created a clever solution together.`},{label:'🗺️ Check the clues again',effect:`${hero} read every clue again and discovered an important hidden meaning.`}]},{prompt:'How should they complete the mission?',options:[{label:'🌟 Try the brave plan',effect:`${hero} took a deep breath and tried the brave plan with great care.`},{label:'💡 Use the clever idea',effect:`${hero} combined all the clues and put a clever new idea into action.`}]}],questions:[{text:`Where did ${hero} begin the adventure?`,answer:place,options:[place,'Dinosaur Island','Moonlight Station']},{text:`Who helped ${hero}?`,answer:friend,options:[friend,'a sleepy giant','a football coach']},{text:'What important object were they searching for?',answer:treasure,options:[treasure,'a rainbow egg','a silver door']},{text:'What mission did they need to complete?',answer:challenge,options:[challenge,'win a swimming race','bake a birthday cake']},{text:'What helped them solve the problem?',answer:'Curiosity, courage and teamwork',options:['Curiosity, courage and teamwork','Giving up quickly','Keeping every idea secret']}]}]}
