async function getDefinition(word){if(simpleDefinitions[word])return simpleDefinitions[word];if(definitionCache[word])return definitionCache[word];try{const response=await fetch(`https://api.dictionaryapi.dev/api/v2/entries/en/${encodeURIComponent(word)}`);if(!response.ok)throw new Error('not found');const data=await response.json(),definition=data?.[0]?.meanings?.flatMap(meaning=>meaning.definitions||[])?.map(item=>item.definition)?.find(Boolean);if(!definition)throw new Error('not found');definitionCache[word]=definition;localStorage.setItem('meehee-definition-cache',JSON.stringify(definitionCache));return definition}catch{return 'We could not find a meaning right now. Try asking a grown-up.'}}
