function updateStoryTicks(){document.querySelectorAll('.story-card').forEach(card=>{const complete=state.completedStories.includes(card.dataset.story);let tick=card.querySelector('.story-complete');if(complete&&!tick){tick=document.createElement('span');tick.className='story-complete';tick.textContent='✓';tick.setAttribute('aria-label','Stars earned from this story today');card.appendChild(tick)}else if(!complete&&tick)tick.remove()})}
function showAllStories(){const panel=document.querySelector('#panel-content'),entries=Object.entries(stories);panel.innerHTML=`<p class="eyebrow">${entries.length} worlds to explore</p><h2 id="panel-title">All stories</h2><p class="panel-intro">Choose any adventure. A green tick means today’s stars have been earned, but you can read it again whenever you like.</p><div class="all-story-grid">${entries.map(([key,story],index)=>`<button class="library-story library-colour-${index%6}" data-library-story="${key}"><span class="library-scene">${story.scene.join(' ')}</span><small>${story.theme}</small><strong>${story.title}</strong><em>${state.completedStories.includes(key)?'✓ Stars earned today':state.readingProgress[key]?.page>1?`▶ Continue from page ${state.readingProgress[key].page}`:'5 pages · 4 choices'}</em></button>`).join('')}</div>`;panel.querySelectorAll('[data-library-story]').forEach(button=>button.addEventListener('click',()=>{panelModal.hidden=true;openStory(button.dataset.libraryStory)}));openModal(panelModal)}

setInterval(()=>{if(!storyModal.hidden&&!document.hidden){state.seconds+=1;updateTimer();if(state.seconds%5===0)save()}},1000);
window.addEventListener('beforeunload',save);document.addEventListener('visibilitychange',()=>{if(document.hidden){if(panelModal.dataset.panel==='parents')closeModals();else save()}});
function openModal(modal){modal.hidden=false;document.body.classList.add('modal-open')}
function closeModals(){if(localStorage.getItem('meehee-onboarding-complete')!=='yes'&&!panelModal.hidden)return;const closingParents=panelModal.dataset.panel==='parents';save();storyModal.hidden=true;panelModal.hidden=true;delete panelModal.dataset.panel;if(closingParents)parentUnlocked=false;document.body.classList.remove('modal-open')}
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',closeModals));document.querySelectorAll('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeModals()}));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModals()});

function getPhonics(word){if(phonics[word])return phonics[word];const chunks=word.match(/[^aeiouy]*[aeiouy]+(?:[^aeiouy](?=[^aeiouy]|$))?|[^aeiouy]+/g);return chunks?.join('–')||word}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function replaceWords(text,map){return Object.entries(map).reduce((result,[word,replacement])=>result.replace(new RegExp(`\\b${word}\\b`,'gi'),match=>{const value=replacement;return match[0]===match[0].toUpperCase()?value[0].toUpperCase()+value.slice(1):value}),text)}
function readerName(){return (state.childName.match(/[A-Za-zÀ-ÿ'-]+/g)||[]).join(' ')||'Reader'}
function personalisedText(text,story){const character=story.nameCharacter;if(!character)return text;const escaped=character.from.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),replacement=character.named?readerName():`${readerName()} the ${character.label}`;return String(text).replace(new RegExp(character.named?`\\b${escaped}\\b`:`\\b(?:(?:a|an|the)\\s+)?${escaped}\\b`,'gi'),replacement)}
function storyHero(story){const words=story.start.match(/[A-Za-z]+/g)||['The hero'];if(words[0]==='Young'||words[0]==='Princess')return words[1];return words[0]}
function earlyReaderPage(story,page){const hero=storyHero(story),pages=[`${hero} has a big day. ${hero} sees something new.`,`${hero} makes a choice. ${hero} goes to look.`,`${hero} meets a kind friend. They find a clue.`,`The way is hard. ${hero} does not stop.`,`${hero} finds the answer. Everyone feels happy.`];return pages[page-1]}
const advancedAdditions=['The situation requires the main character to interpret unfamiliar clues before deciding what action is justified.','That choice creates consequences, so cooperation and clear communication become increasingly important.','By comparing the evidence, the characters can distinguish a useful clue from a distracting detail.','Instead of reacting immediately, they evaluate the risks and adapt their strategy when circumstances change.','The resolution demonstrates how perseverance, imagination, and shared responsibility can transform a difficult situation.'];
function readingText(text,page,story){
  if(state.ageGroup==='4-5'){const character=story.nameCharacter,friend=character?`${readerName()} the ${character.label}`:'a kind friend';return page===3?`${storyHero(story)} meets ${friend}. They find a clue.`:earlyReaderPage(story,page)}
  if(state.ageGroup==='7-9')return personalisedText(text,story);
  if(state.ageGroup==='9-11')return personalisedText(`${replaceWords(text,{big:'immense',careful:'meticulous',carefully:'meticulously',difficult:'challenging',strange:'unfamiliar',help:'assist',idea:'strategy',ideas:'strategies',found:'discovered',looked:'observed',said:'explained'})} ${advancedAdditions[page-1]}`,story);
  const simple=replaceWords(text,{courageous:'brave',enormous:'very big',spectacular:'amazing',extraordinary:'special',mysterious:'strange',ancient:'very old',carefully:'with care',discovered:'found',investigate:'look at',difficult:'hard',destination:'place',revealed:'showed',continued:'went on',celebrated:'cheered',curiosity:'wonder',harmonies:'sounds together'});
  if(state.ageGroup==='5-7')return personalisedText(simple.replace(/; /g,'. ').replace(/, (but|so|and) /gi,'. $1 '),story);
  return simple.replace(/; /g,'. ').replace(/, (but|so|and) /gi,'. $1 ').replace(/, /g,'. ').split(/(?<=[.!?])\s+/).slice(0,2).join(' ');
}
function readingQuestion(text){const simpler=replaceWords(text,{important:'special',object:'thing',searching:'looking',complete:'finish',adventure:'story',famous:'well-known'});return state.ageGroup==='4-5'?'What happens next?':state.ageGroup==='9-11'?`Consider the consequences: ${text}`:simpler}
function levelQuestion(story,index){
  if(state.ageGroup==='4-5'){const hero=storyHero(story);return [{text:'Who is in this story?',answer:hero,options:[hero,'A frog']},{text:`Does ${hero} make a choice?`,answer:'Yes',options:['Yes','No']},{text:`Does ${hero} meet a friend?`,answer:'Yes',options:['Yes','No']},{text:`Does ${hero} stop when it is hard?`,answer:'No',options:['No','Yes']},{text:'How does everyone feel at the end?',answer:'Happy',options:['Happy','Sad']}][index]}
  if(state.ageGroup==='9-11')return [{text:'What can you infer about the main character from their decision to continue?',answer:'They are determined to solve the problem',options:['They are determined to solve the problem','They do not understand the problem','They want somebody else to decide']},{text:'Why is cooperation important after the first decision?',answer:'Different ideas help the characters make progress',options:['Different ideas help the characters make progress','It removes every difficulty immediately','It means clues are no longer needed']},{text:'How do the clues influence the characters’ actions?',answer:'They provide evidence for the next decision',options:['They provide evidence for the next decision','They make every choice random','They only describe the scenery']},{text:'Which approach best shows effective reasoning?',answer:'Checking evidence and adapting the plan',options:['Checking evidence and adapting the plan','Ignoring new information','Repeating a failed plan without thinking']},{text:'Which theme is most strongly supported by the ending?',answer:'Perseverance and teamwork can overcome challenges',options:['Perseverance and teamwork can overcome challenges','Success depends entirely on luck','Difficult problems should be avoided']}][index];
  const question=story.questions[index];return {text:personalisedText(question.text,story),answer:personalisedText(question.answer,story),options:question.options.map(option=>personalisedText(option,story))}
}
function wordify(text){return text.split(/(\s+)/).map(part=>{const clean=part.toLowerCase().replace(/[^a-z]/g,'');return clean?`<button class="word ${state.words.includes(clean)?'learned':''}" data-word="${clean}" aria-label="Hear and save ${clean}">${part}</button>`:part}).join('')}
function bindWords(){storyText.querySelectorAll('.word').forEach(button=>button.addEventListener('click',()=>helpWord(button.dataset.word,button)))}
let readerVoices=[];
function loadReaderVoices(){if('speechSynthesis'in window)readerVoices=speechSynthesis.getVoices()}
if('speechSynthesis'in window){loadReaderVoices();speechSynthesis.addEventListener?.('voiceschanged',loadReaderVoices)}
function chooseReaderVoice(){const english=readerVoices.filter(voice=>voice.lang.toLowerCase().startsWith('en'));return english.sort((a,b)=>voiceScore(b)-voiceScore(a))[0]||null}
function voiceScore(voice){const name=voice.name.toLowerCase(),lang=voice.lang.toLowerCase();let score=0;if(name.includes('natural'))score+=120;if(/sonia|libby|ryan|hazel|samantha|serena|google uk english/.test(name))score+=80;if(name.includes('google'))score+=55;if(name.includes('microsoft'))score+=35;if(lang==='en-gb')score+=45;else if(lang.startsWith('en'))score+=15;if(voice.localService)score+=5;return score}
function speak(words,slow=false){if(!('speechSynthesis'in window))return;loadReaderVoices();speechSynthesis.cancel();const speech=new SpeechSynthesisUtterance(words),preferred=chooseReaderVoice();if(preferred)speech.voice=preferred;speech.lang=preferred?.lang||'en-GB';speech.rate=slow?.68:.92;speech.pitch=1;speech.volume=1;speechSynthesis.speak(speech)}
async function helpWord(word,button){if(!state.words.includes(word)){state.words.push(word);button.classList.add('learned');state.stars+=2}const progress=state.wordProgress[word]||{taps:0,last:today};progress.taps++;progress.last=today;state.wordProgress[word]=progress;save();document.querySelector('.phonics-pop')?.remove();const pop=document.createElement('div');pop.className='phonics-pop';pop.innerHTML=`<span>🔊</span><div class="word-help-copy"><small>Sound it out</small><br><strong>${getPhonics(word)}</strong><small class="meaning-label">What it means</small><p class="word-definition" aria-live="polite">Finding a simple meaning…</p></div><div class="word-help-actions"><button data-hear-word>Hear “${word}” slowly</button><button data-hear-meaning disabled>🔊 Hear meaning</button></div>`;pop.querySelector('[data-hear-word]').addEventListener('click',()=>speak(word,true));storyText.after(pop);speak(word);const definition=await getDefinition(word);if(!pop.isConnected)return;pop.querySelector('.word-definition').textContent=definition;const hearMeaning=pop.querySelector('[data-hear-meaning]');hearMeaning.disabled=false;hearMeaning.addEventListener('click',()=>speak(`${word} means ${definition}`))}
function pageLabel(page){document.querySelector('#story-theme').textContent=`${stories[state.current].theme} · ${readingLevels[state.ageGroup].label} · Page ${page} of 5`;const back=document.querySelector('#story-back');back.hidden=page===1;back.dataset.mode='page';back.textContent='← Previous page'}
function openStory(key){const story=stories[key],saved=state.readingProgress[key];state.current=key;storyRun=saved?.page>1?{page:saved.page,choice:saved.choice,nextIntro:saved.nextIntro||'',answers:[],score:0}:{page:1,choice:null,nextIntro:'',answers:[],score:0};storyModal.dataset.age=state.ageGroup;document.querySelector('#story-title').textContent=story.title;document.querySelector('#story-scene').innerHTML=story.scene.map(x=>`<span aria-hidden="true">${x}</span>`).join('');renderStoryPage();openModal(storyModal)}
function saveStoryPlace(){if(!state.current||!storyRun)return;if(storyRun.page<2){delete state.readingProgress[state.current]}else{state.readingProgress[state.current]={page:storyRun.page,choice:storyRun.choice,nextIntro:storyRun.nextIntro||''}}save()}
function renderStoryPage(){const story=stories[state.current],page=storyRun.page;pageLabel(page);document.querySelector('.phonics-pop')?.remove();const mainText=page===1?story.start:page===2?story.choices[storyRun.choice].text:story.pages[page-3],text=readingText(storyRun.nextIntro?`${storyRun.nextIntro} ${mainText}`:mainText,page,story);storyRun.nextIntro='';storyText.innerHTML=wordify(text);bindWords();saveStoryPlace();if(page===1){choices.innerHTML=`<p>What should happen next?</p>${story.choices.map((c,i)=>`<button class="choice" data-choice="${i}">${c.label}</button>`).join('')}`;choices.querySelectorAll('[data-choice]').forEach(b=>b.addEventListener('click',()=>{storyRun.choice=Number(b.dataset.choice);storyRun.page=2;renderStoryPage()}));return}if(page<5){const decision=story.extraChoices[page-2];choices.innerHTML=`<p>${readingQuestion(decision.prompt)}</p>${decision.options.map((option,i)=>`<button class="choice" data-next-choice="${i}">${option.label}</button>`).join('')}`;choices.querySelectorAll('[data-next-choice]').forEach(button=>button.addEventListener('click',()=>{storyRun.nextIntro=decision.options[Number(button.dataset.nextChoice)].effect;storyRun.page++;renderStoryPage()}));return}choices.innerHTML='<p>You finished the story. Now show what you remember!</p><button class="choice finish" id="story-next">Answer 5 questions 🧠</button>';document.querySelector('#story-next').addEventListener('click',startStoryQuestions)}
function startStoryQuestions(){document.querySelector('.phonics-pop')?.remove();storyRun.answers=[];storyRun.score=0;const back=document.querySelector('#story-back');back.hidden=false;back.dataset.mode='review';back.textContent='← Review story';renderStoryQuestion(0)}
function renderStoryQuestion(index){document.querySelector('.phonics-pop')?.remove();const story=stories[state.current],question=levelQuestion(story,index),questionText=question.text,mixedAnswers=shuffle(question.options);document.querySelector('#story-theme').textContent=`${readingLevels[state.ageGroup].label} · Question ${index+1} of 5`;storyText.innerHTML=`<strong>${questionText}</strong>`;choices.innerHTML=`<button class="choice finish" id="hear-question">🔊 Read question aloud</button>${mixedAnswers.map(option=>`<button class="choice" data-answer="${option.replaceAll('"','&quot;')}">${option}</button>`).join('')}<p id="question-feedback" aria-live="polite"></p>`;document.querySelector('#hear-question').addEventListener('click',()=>speak(questionText));choices.querySelectorAll('[data-answer]').forEach(button=>button.addEventListener('click',()=>answerStoryQuestion(index,button.dataset.answer)))}
function answerStoryQuestion(index,answer){const question=levelQuestion(stories[state.current],index),correct=answer===question.answer;if(correct)storyRun.score++;storyRun.answers.push(answer);choices.querySelectorAll('button').forEach(button=>button.disabled=true);document.querySelector('#question-feedback').textContent=correct?'Correct! Brilliant remembering. ⭐':`Good try. The answer was “${question.answer}”.`;setTimeout(()=>index<4?renderStoryQuestion(index+1):finishStoryQuestions(),900)}
function finishStoryQuestions(){state.quizHistory.push({date:today,story:state.current,score:storyRun.score});save();if(storyRun.score>=4){const earnedToday=state.completedStories.includes(state.current);storyText.innerHTML=`<strong>Fantastic! You scored ${storyRun.score} out of 5.</strong>`;choices.innerHTML=earnedToday?'<p>You already earned this story’s stars today, but brilliant rereading!</p><button class="choice finish" id="collect-story-stars">Finish story ✓</button>':'<p>You remembered the story and earned your reward.</p><button class="choice finish" id="collect-story-stars">Collect 20 stars ⭐</button>';document.querySelector('#collect-story-stars').addEventListener('click',finishStory)}else{storyText.innerHTML=`<strong>You scored ${storyRun.score} out of 5.</strong>`;choices.innerHTML='<p>You need 4 correct answers. Read the story again, then have another try — you can do it!</p><button class="choice finish" id="reread-story">Read the story again 📖</button>';document.querySelector('#reread-story').addEventListener('click',()=>{storyRun={page:1,choice:null,nextIntro:'',answers:[],score:0};renderStoryPage()})}}
function finishStory(){if(!state.completedStories.includes(state.current)){state.stars+=20;state.completedStories.push(state.current)}delete state.readingProgress[state.current];state.storyHistory.push({date:today,story:state.current});state.stories+=1;save();closeModals();showPanel('words')}
document.querySelector('#story-back').addEventListener('click',event=>{document.querySelector('.phonics-pop')?.remove();if(event.currentTarget.dataset.mode==='review'){storyRun.page=5}else{storyRun.page=Math.max(1,storyRun.page-1)}renderStoryPage()});
document.querySelectorAll('.story-card').forEach(card=>card.querySelector('button').addEventListener('click',()=>openStory(card.dataset.story)));document.querySelector('#start-story').addEventListener('click',()=>document.querySelector('.stories').scrollIntoView({behavior:'smooth'}));
document.querySelector('#view-all-stories').addEventListener('click',showAllStories);

function applyProfile(profile){
  state.profile=profile;const sport=profile==='sport';document.body.classList.toggle('sport-mode',sport);
  const activeReader=state.childName||'Reader';document.querySelector('#active-reader-name').textContent=activeReader;
  document.querySelector('.avatar').textContent=state.avatar||'🦊';document.querySelector('.avatar').setAttribute('aria-label',`Open ${activeReader}’s profile`);document.querySelector('#hero-icon').textContent=sport?'⚽':'🏰';
  const reader=state.childName?`${state.childName}’s`:'Your';document.querySelector('#hero-eyebrow').textContent=sport?`${reader} next sporting adventure`:`${reader} next reading adventure`;
  document.querySelector('#hero-title').innerHTML=sport?'Ready to <span>read, play and score?</span>':'Where will your <span>imagination</span> take you?';
  document.querySelector('#hero-description').textContent=sport?'Choose a challenge, tap tricky words for help, and make choices that lead your team to victory.':'Choose a story, tap tricky words for help, and make choices that change what happens next.';
  const card=document.querySelector('#featured-story');card.dataset.story=sport?'sport':'princess';document.querySelector('#featured-emoji').textContent=sport?'⚽🏃🏾':'👸🏾';document.querySelector('#featured-theme').textContent=sport?'Sporting Heroes':'Magical Kingdom';document.querySelector('#featured-title').textContent=sport?'The Last-Minute Goal':'The Princess and the Moon Door';save();
}

function profileChooser(){return `<div class="profile-choice"><button class="profile-option ${state.profile==='princess'?'selected':''}" data-profile="princess"><span>👧🏾</span>Girl adventures<small>Magic and princess stories</small></button><button class="profile-option ${state.profile==='sport'?'selected':''}" data-profile="sport"><span>⚽</span>Boy adventures<small>Sport and team challenges</small></button></div>`}
const avatars=['🦊','🐼','🦁','🐯','🐸','🦄','🤖','🚀','⚽','👑'];
let onboardingDraft={};
function onboardingShell(step,title,copy,content){panelModal.querySelector('.close').hidden=true;return `<div class="onboarding"><div class="setup-progress"><span style="width:${(step+1)/6*100}%"></span></div><small>Grown-up setup · Step ${step+1} of 6</small><h2 id="panel-title">${title}</h2><p class="panel-intro">${copy}</p>${content}</div>`}
function startOnboarding(step=0){const panel=document.querySelector('#panel-content');if(step===0){panel.innerHTML=onboardingShell(step,'Welcome to Help MeeHee Read','Let’s make reading safe, personal and rewarding for your family. This short setup only appears once.',`<div class="setup-picture">📚✨</div><button class="setup-next" data-setup-next>Set up my family →</button>`);panel.querySelector('[data-setup-next]').addEventListener('click',()=>startOnboarding(1))}else if(step===1){panel.innerHTML=onboardingShell(step,'Create a grown-up PIN','This protects names, age levels, rewards and family progress.',`<form class="setup-form"><input id="setup-pin" type="password" minlength="4" maxlength="20" required placeholder="Choose a PIN or password"><input id="setup-pin-confirm" type="password" minlength="4" maxlength="20" required placeholder="Enter it again"><button>Save PIN →</button></form>`);panel.querySelector('form').addEventListener('submit',event=>{event.preventDefault();const pin=event.currentTarget.querySelector('#setup-pin').value.trim(),confirmation=event.currentTarget.querySelector('#setup-pin-confirm').value.trim();if(pin.length<4){window.alert('Please choose at least 4 characters.');return}if(pin!==confirmation){window.alert('Those entries do not match. Please try again.');return}state.parentPin=pin;state.pinConfigured=true;parentUnlocked=true;startOnboarding(2)})}else if(step===2){panel.innerHTML=onboardingShell(step,'Meet your reader','Stories and questions will automatically match this child’s age level.',`<form class="setup-form"><input id="setup-name" maxlength="24" required placeholder="Child’s first name"><select id="setup-age">${Object.entries(readingLevels).map(([key,item])=>`<option value="${key}">Ages ${key} · ${item.stage}</option>`).join('')}</select><select id="setup-style"><option value="princess">Magic adventures</option><option value="sport">Sport adventures</option></select><button>Choose an avatar →</button></form>`);panel.querySelector('form').addEventListener('submit',event=>{event.preventDefault();onboardingDraft.name=event.currentTarget.querySelector('#setup-name').value.trim();onboardingDraft.ageGroup=event.currentTarget.querySelector('#setup-age').value;onboardingDraft.profile=event.currentTarget.querySelector('#setup-style').value;if(!onboardingDraft.name)return;startOnboarding(3)})}else if(step===3){panel.innerHTML=onboardingShell(step,'Choose an avatar','This picture makes it easy to see which child’s profile is active.',`<div class="avatar-picker">${avatars.map(avatar=>`<button data-avatar="${avatar}" aria-label="Choose ${avatar}">${avatar}</button>`).join('')}</div>`);panel.querySelectorAll('[data-avatar]').forEach(button=>button.addEventListener('click',()=>{onboardingDraft.avatar=button.dataset.avatar;startOnboarding(4)}))}else if(step===4){panel.innerHTML=onboardingShell(step,'Add a family reward','This is optional. Choose something meaningful and decide how many stars it needs.',`<form class="setup-form"><input id="setup-reward" maxlength="40" placeholder="e.g. Choose Friday’s dinner"><input id="setup-reward-cost" type="number" min="1" max="9999" placeholder="Stars needed"><button>Save reward →</button></form><button class="setup-skip" data-skip-reward>Skip for now</button>`);const next=()=>startOnboarding(5);panel.querySelector('form').addEventListener('submit',event=>{event.preventDefault();const name=event.currentTarget.querySelector('#setup-reward').value.trim(),cost=Number(event.currentTarget.querySelector('#setup-reward-cost').value);if(name&&Number.isInteger(cost)&&cost>0)onboardingDraft.reward={name,cost};next()});panel.querySelector('[data-skip-reward]').addEventListener('click',next)}else{panel.innerHTML=onboardingShell(step,`Ready for ${escapeHtml(onboardingDraft.name)}’s first adventure!`,'Tap any word to hear it, make choices in every story, answer the questions and earn stars. Reading for ten minutes builds the daily streak.',`<div class="tour-grid"><div>🔊<strong>Tap words</strong><small>Hear and save tricky words</small></div><div>🧭<strong>Make choices</strong><small>Change the story path</small></div><div>⭐<strong>Earn rewards</strong><small>Stories and games earn stars</small></div><div>🔥<strong>Build a streak</strong><small>Read for ten minutes a day</small></div></div><button class="setup-next" data-finish-setup>Start ${escapeHtml(onboardingDraft.name)}’s adventure →</button>`);panel.querySelector('[data-finish-setup]').addEventListener('click',finishOnboarding)}openModal(panelModal)}
function finishOnboarding(){state.childName=onboardingDraft.name;state.ageGroup=onboardingDraft.ageGroup;state.profile=onboardingDraft.profile;state.avatar=onboardingDraft.avatar||'🦊';if(onboardingDraft.reward)state.rewards.push(onboardingDraft.reward);applyProfile(state.profile);localStorage.setItem('meehee-onboarding-complete','yes');parentUnlocked=false;panelModal.querySelector('.close').hidden=false;save();closeModals();onboardingDraft={}}
function showProfilePicker(){const panel=document.querySelector('#panel-content');panel.innerHTML=`<div class="profile-picker"><p class="eyebrow">Who is reading today?</p><h2 id="panel-title">Choose your reader</h2><div class="opening-profiles">${childAccounts.map(child=>`<button data-open-child="${child.id}"><span>${child.avatar||'🦊'}</span><strong>${escapeHtml(child.name)}</strong><small>Ages ${child.ageGroup}</small></button>`).join('')}</div><button class="grownup-entry" data-grownup-entry>🔒 Grown-up area</button></div>`;panel.querySelectorAll('[data-open-child]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.openChild;if(id!==activeChildId){syncChildAccounts();activeChildId=id;applyChildSnapshot(childAccounts.find(child=>child.id===id));localStorage.setItem('meehee-active-child',id)}applyProfile(state.profile);closeModals()}));panel.querySelector('[data-grownup-entry]').addEventListener('click',()=>{panelModal.hidden=true;showPanel('parents')});openModal(panelModal)}
function readerSettings(){const level=readingLevels[state.ageGroup];return `<form class="reader-settings"><label>Child’s first name<input id="child-name" maxlength="24" value="${escapeHtml(state.childName)}" placeholder="e.g. Mia" autocomplete="off"></label><label>Age group<select id="age-group">${Object.entries(readingLevels).map(([key,item])=>`<option value="${key}" ${state.ageGroup===key?'selected':''}>Ages ${key} · ${item.stage}</option>`).join('')}</select></label><label>Profile avatar<select id="reader-avatar">${avatars.map(avatar=>`<option value="${avatar}" ${state.avatar===avatar?'selected':''}>${avatar}</option>`).join('')}</select></label><div class="level-preview"><strong>${level.label}</strong><small>${level.focus}</small></div><small class="parent-lock">🔒 The grown-up password is required to save these changes.</small><button type="submit">Parent: save reader details</button></form>`}
function bindProfileButtons(){document.querySelectorAll('[data-profile]').forEach(button=>button.addEventListener('click',()=>{applyProfile(button.dataset.profile);showPanel('parents')}))}
function bindReaderSettings(){const form=document.querySelector('.reader-settings');form.addEventListener('submit',event=>{event.preventDefault();if(!verifyParent()){form.querySelector('#child-name').value=state.childName;form.querySelector('#age-group').value=state.ageGroup;form.querySelector('#reader-avatar').value=state.avatar;return}state.childName=form.querySelector('#child-name').value.trim();state.ageGroup=form.querySelector('#age-group').value;state.avatar=form.querySelector('#reader-avatar').value;applyProfile(state.profile);showPanel('parents')});form.querySelector('#age-group').addEventListener('change',event=>{const level=readingLevels[event.target.value];form.querySelector('.level-preview').innerHTML=`<strong>${level.label}</strong><small>${level.focus}</small>`})}
function verifyParent(){if(parentUnlocked)return true;if(!state.pinConfigured){const created=window.prompt('Grown-ups: create a private PIN or password (at least 4 characters):');if(created===null)return false;if(created.trim().length<4){window.alert('Please choose at least 4 characters.');return false}const confirmed=window.prompt('Please enter the new PIN again to confirm it:');if(confirmed===null)return false;if(created.trim()!==confirmed.trim()){window.alert('The two entries did not match. Please try again.');return false}state.parentPin=created.trim();state.pinConfigured=true;parentUnlocked=true;save();window.alert('Your grown-up PIN has been created. Keep it somewhere safe.');return true}const entered=window.prompt('Grown-up PIN or password:');if(entered===null)return false;if(entered!==state.parentPin){window.alert('That PIN is not correct. Please ask a grown-up.');return false}parentUnlocked=true;return true}
function wordStage(word){const taps=state.wordProgress[word]?.taps||1;return taps>=6?['🏆','Mastered']:taps>=4?['🌟','Nearly mastered']:taps>=2?['📚','Practising']:['🌱','New word']}
function weekDates(){return Array.from({length:7},(_,index)=>{const date=new Date();date.setDate(date.getDate()-(6-index));return dateKey(date)})}
function weekStart(){const date=new Date();const day=date.getDay()||7;date.setDate(date.getDate()-day+1);return dateKey(date)}
function weeklyProgress(){const start=weekStart(),readingDays=Object.entries(state.readingHistory).filter(([day,seconds])=>day>=start&&seconds>=600).length,storiesRead=new Set(state.storyHistory.filter(item=>item.date>=start).map(item=>item.story)).size,wordsPractised=Object.values(state.wordProgress).filter(item=>item.last>=start).length,passedQuizzes=state.quizHistory.filter(item=>item.date>=start&&item.score>=4).length;return [{icon:'📚',label:'Read for 10 minutes on 4 days',value:readingDays,target:4},{icon:'🗺️',label:'Finish 3 different stories',value:storiesRead,target:3},{icon:'🔤',label:'Practise 5 tricky words',value:wordsPractised,target:5},{icon:'🧠',label:'Pass 2 story quizzes',value:passedQuizzes,target:2}]}
function checkWeeklyAward(){const key=weekStart(),complete=weeklyProgress().every(item=>item.value>=item.target);if(complete&&state.weekReward!==key){state.weekReward=key;state.stars+=50}}
function achievements(){const mastered=state.words.filter(word=>wordStage(word)[1]==='Mastered').length,totalMinutes=Math.floor(Object.values(state.readingHistory).reduce((sum,value)=>sum+Number(value),0)/60),perfect=state.quizHistory.some(item=>item.score===5),uniqueStories=new Set(state.storyHistory.map(item=>item.story)).size;return [{icon:'📖',name:'First Adventure',detail:'Finish your first story',earned:state.stories>=1},{icon:'🧭',name:'Story Explorer',detail:'Finish 5 different stories',earned:uniqueStories>=5},{icon:'👑',name:'Story Legend',detail:'Finish 10 different stories',earned:uniqueStories>=10},{icon:'🔥',name:'Streak Star',detail:'Reach a 5-day streak',earned:state.streak>=5},{icon:'🔤',name:'Word Wizard',detail:'Master 5 tricky words',earned:mastered>=5},{icon:'⏱️',name:'Century Reader',detail:'Read for 100 minutes',earned:totalMinutes>=100},{icon:'🧠',name:'Perfect Memory',detail:'Score 5 out of 5',earned:perfect},{icon:'🌍',name:'World Traveller',detail:'Explore 15 stories',earned:uniqueStories>=15}]}
function challengePanel(){const progress=weeklyProgress(),complete=progress.every(item=>item.value>=item.target),rewarded=state.weekReward===weekStart();return `<p class="eyebrow">A new mission every Monday</p><h2 id="panel-title">Weekly challenges</h2><p class="panel-intro">Complete all four challenges to earn 50 bonus stars.</p><div class="challenge-list">${progress.map(item=>{const done=item.value>=item.target;return `<div class="challenge-row ${done?'done':''}"><span>${done?'✓':item.icon}</span><div><strong>${item.label}</strong><small>${Math.min(item.value,item.target)} of ${item.target}</small><i><b style="width:${Math.min(100,item.value/item.target*100)}%"></b></i></div></div>`}).join('')}</div><div class="weekly-prize ${complete?'complete':''}">${rewarded?'🏆 50 bonus stars collected this week!':complete?'🎉 Challenge complete — your 50 stars have been added!':'⭐ Weekly prize: 50 stars'}</div><p class="eyebrow">Your collection</p><h2>Achievement badges</h2><div class="badge-grid">${achievements().map(badge=>`<div class="achievement ${badge.earned?'earned':'locked'}"><span>${badge.earned?badge.icon:'🔒'}</span><strong>${badge.name}</strong><small>${badge.detail}</small></div>`).join('')}</div>`}
function parentDashboard(){const days=weekDates(),start=weekStart(),max=Math.max(600,...days.map(day=>state.readingHistory[day]||0)),recent=state.quizHistory.slice(-5).reverse(),weekQuizzes=state.quizHistory.filter(item=>item.date>=start),weekStories=state.storyHistory.filter(item=>item.date>=start).length,accuracy=weekQuizzes.length?Math.round(weekQuizzes.reduce((sum,item)=>sum+item.score,0)/(weekQuizzes.length*5)*100):0,mastered=state.words.filter(word=>wordStage(word)[1]==='Mastered').length;return `<h3 class="report-title">📋 This week’s report</h3><div class="dashboard-summary"><div><strong>${Math.round(days.reduce((sum,day)=>sum+(state.readingHistory[day]||0),0)/60)}</strong><small>minutes read</small></div><div><strong>${weekStories}</strong><small>stories finished</small></div><div><strong>${accuracy}%</strong><small>quiz accuracy</small></div><div><strong>${mastered}</strong><small>words mastered</small></div></div><h3>Last 7 days</h3><div class="week-chart">${days.map(day=>{const seconds=state.readingHistory[day]||0;return `<div><span style="height:${Math.max(4,Math.round(seconds/max*100))}%"></span><strong>${Math.round(seconds/60)}m</strong><small>${new Date(`${day}T12:00:00`).toLocaleDateString('en-GB',{weekday:'short'})}</small></div>`}).join('')}</div><h3>Recent comprehension</h3>${recent.length?`<div class="quiz-history">${recent.map(item=>`<div><span>${stories[item.story]?.scene?.[0]||'📖'}</span><strong>${escapeHtml(stories[item.story]?.title||'Story')}</strong><em>${item.score}/5</em></div>`).join('')}</div>`:'<p class="empty-state">Quiz results will appear here.</p>'}`}
function bindPinForm(){document.querySelector('.pin-form').addEventListener('submit',event=>{event.preventDefault();const pin=event.currentTarget.querySelector('#new-parent-pin').value.trim(),confirm=event.currentTarget.querySelector('#confirm-parent-pin').value.trim();if(pin.length<4){window.alert('Please choose at least 4 characters.');return}if(pin!==confirm){window.alert('The two PIN entries do not match.');return}state.parentPin=pin;state.pinConfigured=true;save();event.currentTarget.reset();window.alert('The new parent PIN has been saved.')})}
function bindParentSignOut(){document.querySelector('#parent-sign-out').addEventListener('click',()=>{parentUnlocked=false;closeModals();window.alert('The grown-up area is locked. The PIN will be needed to open it again.')})}
function childManager(){return `<section class="child-manager"><div class="child-manager-title"><div><p class="eyebrow">Family readers</p><h3>Children’s accounts</h3></div><small>${childAccounts.length}/5 profiles</small></div><div class="child-account-list">${childAccounts.map(child=>`<div class="child-account ${child.id===activeChildId?'active':''}"><span>${child.avatar||'🦊'}</span><div><strong>${escapeHtml(child.name)}</strong><small>Ages ${child.ageGroup}${child.id===activeChildId?' · Currently reading':''}</small></div>${child.id===activeChildId?'<em>Active</em>':`<button data-switch-child="${child.id}">Switch</button>`}${childAccounts.length>1?`<button class="delete-child" data-delete-child="${child.id}" aria-label="Remove ${escapeHtml(child.name)}">×</button>`:''}</div>`).join('')}</div>${childAccounts.length<5?`<form class="add-child-form"><input id="new-child-name" maxlength="24" required placeholder="Child’s first name"><select id="new-child-age">${Object.entries(readingLevels).map(([key,item])=>`<option value="${key}">Ages ${key} · ${item.stage}</option>`).join('')}</select><select id="new-child-style"><option value="princess">Magic adventures</option><option value="sport">Sport adventures</option></select><button>Add child</button></form>`:'<p class="profile-limit">Maximum of five children reached.</p>'}</section>`}
function switchChild(id){if(id===activeChildId)return;syncChildAccounts();const child=childAccounts.find(item=>item.id===id);if(!child)return;activeChildId=id;applyChildSnapshot(child);localStorage.setItem('meehee-active-child',id);applyProfile(state.profile);showPanel('parents')}
function removeChildAccount(id){const child=childAccounts.find(item=>item.id===id);if(!child||childAccounts.length===1)return;if(!window.confirm(`Remove ${child.name} and all of their saved progress from this device?`))return;childAccounts=childAccounts.filter(item=>item.id!==id);if(activeChildId===id){activeChildId=childAccounts[0].id;applyChildSnapshot(childAccounts[0]);applyProfile(state.profile)}localStorage.setItem('meehee-child-accounts',JSON.stringify(childAccounts));localStorage.setItem('meehee-active-child',activeChildId);showPanel('parents')}
function bindChildManager(){document.querySelectorAll('[data-switch-child]').forEach(button=>button.addEventListener('click',()=>switchChild(button.dataset.switchChild)));document.querySelectorAll('[data-delete-child]').forEach(button=>button.addEventListener('click',()=>removeChildAccount(button.dataset.deleteChild)));const form=document.querySelector('.add-child-form');if(form)form.addEventListener('submit',event=>{event.preventDefault();if(childAccounts.length>=5)return;syncChildAccounts();const name=form.querySelector('#new-child-name').value.trim(),ageGroup=form.querySelector('#new-child-age').value,profile=form.querySelector('#new-child-style').value;if(!name)return;const id=`child-${Date.now()}`,newChild={id,name,ageGroup,profile,avatar:profile==='sport'?'⚽':'🦊',readingProgress:{},stars:0,words:[],stories:0,seconds:0,rewarded:false,rewards:JSON.parse(JSON.stringify(state.rewards)),hiddenRewards:[],gameStars:0,streak:0,lastCompleted:'',completedStories:[],wordProgress:{},readingHistory:{},quizHistory:[],storyHistory:[],weekReward:'',readingDay:today,storyDay:today,gameDay:today};childAccounts.push(newChild);activeChildId=id;applyChildSnapshot(newChild);localStorage.setItem('meehee-active-child',id);applyProfile(profile);showPanel('parents')})}
function removeWord(word){if(!verifyParent())return;state.words=state.words.filter(saved=>saved!==word);delete state.wordProgress[word];save();showPanel('words')}
function removeReward(kind,id){if(!verifyParent())return;if(kind==='built-in')state.hiddenRewards.push(id);else state.rewards.splice(Number(id),1);save();showPanel('rewards')}
function redeemReward(name,cost){if(!verifyParent())return;if(state.stars<cost){window.alert('There are not enough stars for this reward yet.');return}if(!window.confirm(`Approve “${name}” for ${cost} stars?`))return;state.stars-=cost;save();showPanel('rewards');window.alert(`${name} approved! ${cost} stars have been used.`)}
function showPanel(type){
  if(type==='parents'&&!verifyParent())return;
  panelModal.dataset.panel=type;
  const panel=document.querySelector('#panel-content');
  if(type==='words'){
    panel.innerHTML=`<p class="eyebrow">Your reading toolkit</p><h2 id="panel-title">My word journey</h2><p class="panel-intro">Every time you practise a word, it moves closer to being mastered.</p>${state.words.length?`<div class="word-list">${state.words.map(w=>{const stage=wordStage(w);return `<div class="saved-word"><span>${stage[0]}</span><div><strong>${w}</strong><small>${getPhonics(w)} · ${stage[1]} · ${state.wordProgress[w]?.taps||1} practices</small></div><div class="row-actions"><button data-speak="${w}">🔊 Practise</button><button class="remove-button" data-remove-word="${w}">Remove</button></div></div>`}).join('')}</div>`:'<div class="empty-state">📖<br>Tap any word inside a story and it will begin its learning journey.</div>'}`;panel.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',()=>{const word=b.dataset.speak,progress=state.wordProgress[word]||{taps:0,last:today};progress.taps++;progress.last=today;state.wordProgress[word]=progress;save();speak(word,true);showPanel('words')}));panel.querySelectorAll('[data-remove-word]').forEach(b=>b.addEventListener('click',()=>removeWord(b.dataset.removeWord)));
  }else if(type==='rewards'){
    const builtIns=[{id:'treat',icon:'🍬',name:'A shop treat',cost:80},{id:'money',icon:'💰',name:'Pocket money bonus',cost:150},{id:'film',icon:'🎬',name:'Choose family film',cost:200}].filter(r=>!state.hiddenRewards.includes(r.id));
    const availableStars=Number(state.stars)||0,rewards=[...builtIns.map(r=>({...r,kind:'built-in'})),...state.rewards.map((r,index)=>({id:String(index),icon:'🎁',name:r.name,cost:Number(r.cost)||0,kind:'custom'}))];panel.innerHTML=`<p class="eyebrow">Stars become smiles</p><h2 id="panel-title">My rewards</h2><p class="panel-intro">You have <strong>${availableStars} stars</strong>. Stars are used when a grown-up approves a reward, and every child has their own balance.</p><div class="reward-list">${rewards.map(r=>{const ready=availableStars>=r.cost,needed=Math.max(0,r.cost-availableStars);return `<div class="reward-row"><span>${r.icon}</span><div><strong>${r.name}</strong><small>${r.cost} stars</small></div><div class="row-actions"><button class="claim-button" data-claim="${r.id}" ${ready?'':'disabled'}>${ready?'Ask grown-up':`Need ${needed} more ⭐`}</button><button class="remove-button" data-remove-reward="${r.id}" data-kind="${r.kind}">Remove</button></div></div>`}).join('')}</div>`;
    panel.querySelectorAll('[data-claim]').forEach(button=>{const reward=rewards.find(r=>r.id===button.dataset.claim);button.addEventListener('click',()=>redeemReward(reward.name,reward.cost))});panel.querySelectorAll('[data-remove-reward]').forEach(button=>button.addEventListener('click',()=>removeReward(button.dataset.kind,button.dataset.removeReward)));
  }else if(type==='achievements'){
    panel.innerHTML=challengePanel();
  }else{
    panel.innerHTML=`<div class="parent-dashboard-head"><div><p class="eyebrow">Grown-up dashboard</p><h2 id="panel-title">${state.childName?`${escapeHtml(state.childName)}’s`:'Reader'} progress</h2></div><button id="parent-sign-out">🔒 Lock grown-up area</button></div>${childManager()}${parentDashboard()}<p class="eyebrow">Reader details</p>${readerSettings()}<p class="eyebrow">Choose your style</p>${profileChooser()}<div class="parent-code"><small>Progress proof code</small><strong>ME-${state.stories+24}R</strong><small>Changes as stories are completed</small></div><p class="timer-note">Reading time counts only while a story is open and visible. A 10-minute day keeps the streak going.</p><label class="form-label" for="reward-name">Add a family reward</label><form class="custom-reward"><input id="reward-name" required maxlength="40" aria-label="Custom reward" placeholder="e.g. Choose Friday's dinner"><input class="reward-cost" required type="number" min="1" max="9999" step="1" aria-label="Stars needed" placeholder="Stars needed"><button>Add reward</button></form><small class="reward-help">Choose any value from 1 to 9,999 stars.</small><label class="form-label" for="new-parent-pin">Change parent PIN</label><form class="pin-form"><input id="new-parent-pin" type="password" minlength="4" maxlength="20" required placeholder="New PIN"><input id="confirm-parent-pin" type="password" minlength="4" maxlength="20" required placeholder="Confirm PIN"><button>Save new PIN</button></form>`;bindParentSignOut();bindChildManager();bindReaderSettings();bindProfileButtons();bindPinForm();panel.querySelector('.custom-reward').addEventListener('submit',e=>{e.preventDefault();const name=e.currentTarget.querySelector('#reward-name').value.trim();const cost=Number(e.currentTarget.querySelector('.reward-cost').value);if(!name||!Number.isInteger(cost)||cost<1||cost>9999)return;state.rewards.push({name,cost});save();showPanel('rewards')});
  }openModal(panelModal)
}
const gameInfo={ninja:['🥷','Word Ninja'],sounds:['🏁','Sound-It-Out Race'],treasure:['🗺️','Word Treasure Hunt'],sentence:['🧩','Sentence Builder'],rhyme:['🫧','Rhyme Time'],missing:['🔎','Missing Word Mystery'],memory:['🃏','Tricky Word Match'],rescue:['🦸🏾','Story Rescue'],spell:['🚀','Spell Blaster'],silly:['🤪','Silly Story Studio']};
let gameSession=null;
const fallbackWords=['mysterious','courageous','enormous','surprising','spectacular','gigantic'];
function shuffle(items){return [...items].sort(()=>Math.random()-.5)}
function gameWords(){return [...new Set([...state.words,...fallbackWords])].slice(0,6)}
function plainText(text){return String(text).replace(/<[^>]*>/g,'').replace(/&[^;]+;/g,' ')}
function gameHeader(key,instructions){const [icon,title]=gameInfo[key];return `<div class="game-stage"><div class="game-icon">${icon}</div><p class="eyebrow">Games Arcade</p><h2 id="panel-title">${title}</h2><p class="panel-intro">${instructions}</p><button class="game-listen" data-speak-game="${escapeHtml(plainText(instructions))}">🔊 Read instructions again</button><div class="game-hud"><span>⭐ Score: <b id="round-score">${gameSession?.score||0}</b></span><span>🎮 Today: ${state.gameStars}/30</span></div><div id="game-board"></div></div>`}
panelModal.addEventListener('click',event=>{const button=event.target.closest('[data-speak-game]');if(button)speak(button.dataset.speakGame,button.dataset.slow==='yes')});
function awardGameStars(points){const earned=Math.max(0,Math.min(points,10,30-state.gameStars));state.gameStars+=earned;state.stars+=earned;save();return earned}
function finishGame(message='Great reading practice!'){const earned=awardGameStars(gameSession.score);document.querySelector('#game-board').innerHTML=`<div class="game-finish">🎉<strong>+${earned} stars</strong><p>${message}</p><small>${state.gameStars}/30 game stars earned today</small><br><button class="game-next" data-play-again>Play again</button></div>`;document.querySelector('[data-play-again]').addEventListener('click',()=>startGame(gameSession.key))}
function startQuiz(key,instructions,questions,speakTarget=false){gameSession={key,score:0,round:0,questions:shuffle(questions).slice(0,5)};const panel=document.querySelector('#panel-content');panel.innerHTML=gameHeader(key,instructions);openModal(panelModal);renderQuizRound(speakTarget)}
function renderQuizRound(speakTarget=false){if(gameSession.round>=gameSession.questions.length){finishGame();return}const q=gameSession.questions[gameSession.round],repeatText=speakTarget?(q.target||q.answer):plainText(q.prompt);const board=document.querySelector('#game-board');board.innerHTML=`<p class="game-prompt">${q.prompt}</p><button class="game-listen repeat-round" data-speak-game="${escapeHtml(repeatText)}" ${speakTarget?'data-slow="yes"':''}>🔊 ${speakTarget?'Repeat word':'Read question again'}</button><div class="game-options">${shuffle(q.options).map(option=>`<button class="game-option" data-answer="${option.replaceAll('"','&quot;')}">${option}</button>`).join('')}</div><div class="game-feedback"></div>`;if(speakTarget)speak(q.target||q.answer);board.querySelectorAll('[data-answer]').forEach(button=>button.addEventListener('click',()=>{const correct=button.dataset.answer===q.answer;button.classList.add(correct?'correct':'wrong');board.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);if(correct)gameSession.score+=2;document.querySelector('#round-score').textContent=gameSession.score;board.querySelector('.game-feedback').textContent=correct?'Brilliant! +2 ⭐':`Good try — the answer was “${q.answer}”.`;setTimeout(()=>{gameSession.round++;renderQuizRound(speakTarget)},850)}))}

function ninjaGame(){const words=gameWords();const questions=words.map(word=>({prompt:'Tap the word you hear 🔊',target:word,answer:word,options:shuffle([word,...shuffle(words.filter(w=>w!==word)).slice(0,2)])}));startQuiz('ninja','Listen carefully and catch the right word before it escapes!',questions,true)}
function soundGame(){const words=gameWords();const questions=words.map(word=>({prompt:`Which sound pattern builds <strong>${word}</strong>?`,answer:getPhonics(word),options:shuffle([getPhonics(word),word.slice(0,2)+'–'+word.slice(2),word.split('').reverse().join('–')])}));startQuiz('sounds','Choose the phonics sounds that build each word.',questions)}
function treasureGame(){startQuiz('treasure','Follow each sound clue to uncover the treasure!',[{prompt:'Find something beginning with “ch”',answer:'🪑 chair',options:['🪑 chair','🍎 apple','🌙 moon','🐸 frog']},{prompt:'Find something beginning with “sh”',answer:'👟 shoe',options:['👟 shoe','🐱 cat','🚲 bike','🍰 cake']},{prompt:'Find something ending with “ck”',answer:'🦆 duck',options:['🦆 duck','🌳 tree','🐝 bee','🐟 fish']},{prompt:'Find something beginning with “b”',answer:'⚽ ball',options:['⚽ ball','☀️ sun','🧀 cheese','🦊 fox']},{prompt:'Find something beginning with “r”',answer:'🚀 rocket',options:['🚀 rocket','👑 crown','⭐ star','🐶 dog']}])}
function rhymeGame(){startQuiz('rhyme','Pop the word that rhymes with the clue!',[{prompt:'What rhymes with <strong>cat</strong>?',answer:'hat',options:['hat','dog','sun','fish']},{prompt:'What rhymes with <strong>moon</strong>?',answer:'spoon',options:['spoon','star','book','cake']},{prompt:'What rhymes with <strong>play</strong>?',answer:'day',options:['day','ball','tree','ship']},{prompt:'What rhymes with <strong>light</strong>?',answer:'kite',options:['kite','cloud','door','fox']},{prompt:'What rhymes with <strong>read</strong>?',answer:'seed',options:['seed','page','word','look']}])}
function missingGame(){startQuiz('missing','Use the sentence clues to find the missing word.',[{prompt:'The dinosaur hid behind the enormous ___.',answer:'tree',options:['tree','spoon','sock','moon']},{prompt:'The rocket blasted into ___.',answer:'space',options:['space','puddle','kitchen','pillow']},{prompt:'The goalkeeper caught the ___.',answer:'ball',options:['ball','book','cake','boat']},{prompt:'The princess opened the silver ___.',answer:'door',options:['door','shoe','cloud','fish']},{prompt:'We use our eyes to ___ a book.',answer:'read',options:['read','bounce','taste','kick']}])}
function rescueGame(){startQuiz('rescue','Every correct answer helps your hero cross the bridge!',[{prompt:'The bridge is shaking! Choose the word meaning very big.',answer:'enormous',options:['enormous','tiny','quiet','slow']},{prompt:'A dragon blocks the path. Choose the bravest word.',answer:'courageous',options:['courageous','sleepy','little','soft']},{prompt:'The key is hidden. Which word means not ordinary?',answer:'unusual',options:['unusual','normal','plain','same']},{prompt:'The door sparkles brightly. Which word means amazing to see?',answer:'spectacular',options:['spectacular','dull','empty','silent']},{prompt:'You saved the story! Which word means calm and quiet?',answer:'peaceful',options:['peaceful','noisy','angry','rough']}])}

function sentenceGame(){const rounds=[['The','friendly','dragon','waved.'],['Milo','flew','to','Mars.'],['Kai','kicked','the','ball.']];gameSession={key:'sentence',score:0,round:0,rounds};const panel=document.querySelector('#panel-content');panel.innerHTML=gameHeader('sentence','Tap the word cards in the correct order.');openModal(panelModal);renderSentence()}
function renderSentence(){if(gameSession.round>=gameSession.rounds.length){finishGame('Your sentences make perfect sense!');return}const answer=gameSession.rounds[gameSession.round];let built=[];const board=document.querySelector('#game-board');board.innerHTML=`<p class="game-prompt">Build the sentence</p><div class="built-word" id="built-sentence">Tap words below…</div><div class="letter-tray">${shuffle(answer).map((word,index)=>`<button class="letter-button" data-word="${word}" data-index="${index}">${word}</button>`).join('')}</div><button class="game-next" id="check-sentence">Check sentence</button><div class="game-feedback"></div>`;board.querySelectorAll('[data-word]').forEach(b=>b.addEventListener('click',()=>{built.push(b.dataset.word);b.disabled=true;document.querySelector('#built-sentence').textContent=built.join(' ')}));document.querySelector('#check-sentence').addEventListener('click',()=>{const correct=built.join(' ')===answer.join(' ');if(correct)gameSession.score+=3;board.querySelector('.game-feedback').textContent=correct?'Perfect sentence! ⭐':`Almost! It was: ${answer.join(' ')}`;document.querySelector('#round-score').textContent=gameSession.score;setTimeout(()=>{gameSession.round++;renderSentence()},900)})}

function spellGame(){gameSession={key:'spell',score:0,round:0,rounds:shuffle(gameWords()).slice(0,3)};const panel=document.querySelector('#panel-content');panel.innerHTML=gameHeader('spell','Listen, then blast the letters into the correct order.');openModal(panelModal);renderSpell()}
function renderSpell(){if(gameSession.round>=gameSession.rounds.length){finishGame('Fantastic spelling blast!');return}const word=gameSession.rounds[gameSession.round];let built='';const board=document.querySelector('#game-board');board.innerHTML=`<p class="game-prompt">Spell the word you hear <button class="game-next" id="hear-spell">🔊 Hear</button></p><div class="built-word" id="spell-built">_</div><div class="letter-tray">${shuffle(word.split('')).map((letter,index)=>`<button class="letter-button" data-letter="${letter}" data-index="${index}">${letter}</button>`).join('')}</div><button class="game-next" id="check-spell">Fire! 🚀</button><div class="game-feedback"></div>`;speak(word);document.querySelector('#hear-spell').addEventListener('click',()=>speak(word,true));board.querySelectorAll('[data-letter]').forEach(b=>b.addEventListener('click',()=>{built+=b.dataset.letter;b.disabled=true;document.querySelector('#spell-built').textContent=built}));document.querySelector('#check-spell').addEventListener('click',()=>{const correct=built===word;if(correct)gameSession.score+=3;board.querySelector('.game-feedback').textContent=correct?'Direct hit! ⭐':`The word was ${word}.`;document.querySelector('#round-score').textContent=gameSession.score;setTimeout(()=>{gameSession.round++;renderSpell()},900)})}

function memoryGame(){const words=gameWords().slice(0,3);const cards=shuffle(words.flatMap(word=>[{id:word,label:word},{id:word,label:'🔊 '+getPhonics(word)}]));gameSession={key:'memory',score:0,first:null,matched:0};const panel=document.querySelector('#panel-content');panel.innerHTML=gameHeader('memory','Match each tricky word with its sound pattern.');openModal(panelModal);const board=document.querySelector('#game-board');board.innerHTML=`<div class="memory-grid">${cards.map((card,index)=>`<button class="memory-card" data-card="${index}" data-id="${card.id}" data-label="${card.label}">?</button>`).join('')}</div><div class="game-feedback"></div>`;board.querySelectorAll('[data-card]').forEach(button=>button.addEventListener('click',()=>flipMemory(button)))}
function flipMemory(button){if(button.classList.contains('revealed')||button.classList.contains('matched'))return;button.classList.add('revealed');button.textContent=button.dataset.label;if(!gameSession.first){gameSession.first=button;return}const first=gameSession.first;gameSession.first=null;if(first.dataset.id===button.dataset.id){first.classList.add('matched');button.classList.add('matched');gameSession.matched++;gameSession.score+=3;document.querySelector('#round-score').textContent=gameSession.score;if(gameSession.matched===3)setTimeout(()=>finishGame('Memory master! You matched every pair.'),600)}else{setTimeout(()=>{[first,button].forEach(b=>{b.classList.remove('revealed');b.textContent='?'})},700)}}

function sillyGame(){gameSession={key:'silly',score:5};const panel=document.querySelector('#panel-content');panel.innerHTML=gameHeader('silly','Choose three ingredients and create a hilarious story.');openModal(panelModal);const board=document.querySelector('#game-board');board.innerHTML=`<div class="game-options"><label>Hero<select id="silly-hero"><option>enormous hamster</option><option>football-playing dragon</option><option>dancing astronaut</option></select></label><label>Action<select id="silly-action"><option>juggled jelly</option><option>flew backwards</option><option>sang to the moon</option></select></label><label>Place<select id="silly-place"><option>inside a castle</option><option>at the stadium</option><option>on Dinosaur Island</option></select></label></div><button class="game-next" id="make-story">Make my story!</button><div id="silly-result"></div>`;document.querySelector('#make-story').addEventListener('click',()=>{const hero=document.querySelector('#silly-hero').value,action=document.querySelector('#silly-action').value,place=document.querySelector('#silly-place').value;document.querySelector('#silly-result').innerHTML=`<p class="story-result">Once upon a time, an ${hero} ${action} ${place}. Everyone laughed so loudly that a surprised moon fox fell off its chair!</p><button class="game-next" id="finish-silly">I read my silly story!</button>`;document.querySelector('#finish-silly').addEventListener('click',()=>finishGame('Wonderful! Make another and read it aloud.'))})}

function startGame(key){({ninja:ninjaGame,sounds:soundGame,treasure:treasureGame,sentence:sentenceGame,rhyme:rhymeGame,missing:missingGame,memory:memoryGame,rescue:rescueGame,spell:spellGame,silly:sillyGame})[key]()}
document.querySelectorAll('[data-game]').forEach(button=>button.addEventListener('click',()=>startGame(button.dataset.game)));
function initialEntry(){const complete=localStorage.getItem('meehee-onboarding-complete')==='yes';if(!complete){if(state.pinConfigured&&state.childName&&state.childName!=='Reader'){localStorage.setItem('meehee-onboarding-complete','yes')}else{startOnboarding();return}}if(childAccounts.length>1)showProfilePicker()}
document.querySelectorAll('[data-open]').forEach(button=>button.addEventListener('click',()=>showPanel(button.dataset.open)));document.querySelector('.avatar').addEventListener('click',()=>showPanel('parents'));applyProfile(state.profile);setTimeout(initialEntry,150);

